import {Link} from '@primer/react'

import type {FormErrorMessage as FormErrorMessageType} from '../helpers/definition-form-types'

export function FormErrorMessage({error}: {error: FormErrorMessageType}) {
  if (typeof error === 'string') return <>{error}</>

  return (
    <>
      {error.map(segment =>
        typeof segment === 'string' ? (
          segment
        ) : (
          <Link key={segment.targetId} href={`#${segment.targetId}`} inline>
            {segment.text}
          </Link>
        ),
      )}
    </>
  )
}

try{ FormErrorMessage.displayName ||= 'FormErrorMessage' } catch {}